using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using OwnLabView;
internal sealed class ClassGraph {
 public readonly TypeImport.Session N;public readonly string Path,Folder;public readonly object VI;public readonly uint Diagram;Dictionary<string,object> styles;short x=40;
 public ClassGraph(TypeImport.Session n,string path,string folder,bool existing=false){N=n;Path=path;Folder=folder;if(!existing){if(File.Exists(path))throw new IOException("Authoring target exists.");N.Call("Native_Create",D("output_path",path));}VI=N.Open(path);Diagram=Convert.ToUInt32(N.Call("Native_GetRootDiagram",D("target_path",path),"diagram_id")["diagram_id"]);styles=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(System.IO.Path.Combine(Storage.Root,@"recipes\ni-styles.json"))));}
 public static Dictionary<string,object> D(params object[] a){var d=new Dictionary<string,object>();for(int i=0;i<a.Length;i+=2)d.Add((string)a[i],a[i+1]);return d;}
 public uint Node(string style){x+=120;return Convert.ToUInt32(N.Call("Own20261012_GuardedAddNodeInDiagram",D("target_path",Path,"owner_diagram_id",Diagram,"style",Convert.ToUInt32(styles[style]),"x",x,"y",(short)150),"object_id")["object_id"]);}
 public uint Sub(string path){x+=120;return Convert.ToUInt32(N.Call("Native_AddSubVIInDiagram",D("target_path",Path,"owner_diagram_id",Diagram,"subvi_path",path,"x",x,"y",(short)150),"object_id")["object_id"]);}
 public Dictionary<string,uint> Pins(uint node){var d=new Dictionary<string,uint>();foreach(object raw in (IEnumerable)N.Call("Native_GetNodeTerminals",D("node_id",node),"terminal_ids")["terminal_ids"]){uint t=Convert.ToUInt32(raw);string name=Convert.ToString(N.Call("Native_GetTerminalName",D("terminal_id",t),"terminal_name")["terminal_name"]);if(name.Length!=0&&!d.ContainsKey(name))d.Add(name,t);}return d;}
 public void Wire(uint a,uint b){N.Call("Native_Wire",D("source_terminal",a,"sink_terminal",b));}
 public static uint Err(Dictionary<string,uint> p){return p.Single(v=>v.Key.StartsWith("error in")).Value;}
 public uint Control(uint terminal,string label){var c=N.Call("Own20261012_CreateControlFromTerminal",D("terminal_id",terminal),"control_id");N.Call("Native_SetControlLabel",D("control_id",c["control_id"],"label",label));return Convert.ToUInt32(c["control_id"]);}
 public void Indicator(uint terminal,string label){var c=N.Call("Own20261012_CreateIndicatorFromTerminal",D("terminal_id",terminal),"control_id");N.Call("Native_SetControlLabel",D("control_id",c["control_id"],"label",label));}
 public Dictionary<string,uint> Invoke(uint reference,string method,string verifiedPrivateUid=null){uint id=Node("Invoke Node");Wire(reference,Pins(id)["reference"]);var info=N.Call("Own20261012_GetInvokeInfo",D("invoke_id",id),"class_name","supported_methods");Storage.WriteNew(System.IO.Path.Combine(Folder,"methods-"+id+".json"),info);var rows=((IEnumerable)info["supported_methods"]).Cast<object>().Select(o=>((IEnumerable)o).Cast<object>().Select(Convert.ToString).ToArray()).ToArray();string uid=verifiedPrivateUid??rows.Where(row=>row.Any(s=>s.Equals(method,StringComparison.OrdinalIgnoreCase))).Select(row=>row[0]).Single();N.Call("Own20261012_SelectMethod",D("invoke_id",id,"method",uid));var pins=Pins(id);var extra=N.Call("Own20261012_GetInvokeTerminals",D("invoke_id",id),"input_terminal_ids","output_terminal_ids");Storage.WriteNew(System.IO.Path.Combine(Folder,"invoke-terms-"+id+".json"),extra);foreach(object t in (IEnumerable)extra["output_terminal_ids"]){string name=Convert.ToString(N.Call("Native_GetTerminalName",D("terminal_id",t),"terminal_name")["terminal_name"]);pins[name]=Convert.ToUInt32(t);}return pins;}
 public Dictionary<string,uint> Property(uint reference,string property){uint id=Node("Property Node");Wire(reference,Pins(id)["reference"]);var info=N.Call("Own20261012_GetPropertyInfo",D("property_id",id),"class_name","supported_properties");Storage.WriteNew(System.IO.Path.Combine(Folder,"properties-"+id+".json"),info);var rows=((IEnumerable)info["supported_properties"]).Cast<object>().Select(o=>((IEnumerable)o).Cast<object>().Select(Convert.ToString).ToArray()).ToArray();string uid=rows.Where(row=>row.Any(s=>s.Equals(property,StringComparison.OrdinalIgnoreCase))).Select(row=>row[0]).Single();N.Call("Own20261012_SelectProperties",D("property_id",id,"property_id_strings",new[]{uid},"allow_alternate_names",false));return Pins(id);}
 public uint Close(uint reference,uint error){var p=Pins(Node("Close Reference"));Wire(reference,p["reference"]);Wire(error,Err(p));return p["error out"];}
 public void Save(){LabView.Invoke(VI,"SaveInstrument",BindingFlags.InvokeMethod,Path,false,false);int state=Convert.ToInt32(LabView.Invoke(VI,"ExecState",BindingFlags.GetProperty));if(state!=1){var nodes=new List<object>();foreach(object raw in (IEnumerable)N.Call("Native_GetDiagramObjects",D("diagram_id",Diagram),"object_ids")["object_ids"]){var kind=N.Call("Native_GetObjectInfo",D("object_id",raw),"class_name");if(new[]{"Invoke","SubVI"}.Contains(Convert.ToString(kind["class_name"])))nodes.Add(new{id=raw,kind=kind,pins=Pins(Convert.ToUInt32(raw))});}Storage.WriteNew(System.IO.Path.Combine(Folder,"uncompiled-nodes.json"),nodes);throw new IOException("Authored helper not compiled: "+state);}}
}
